+            if (Enum.TryParse<ShipmentStatus>(status, true, out var parsedStatus))
+                query = query.Where(s => s.Status == parsedStatus);
+
+            if (!string.IsNullOrWhiteSpace(search))
+                query = query.Where(s =>
+                    s.TrackingNumber.Contains(search) ||
+                    s.Destination.Contains(search) ||
+                    s.RecipientName.Contains(search));
+
+            var shipments = await query.OrderByDescending(s => s.ShippedDate)
+                .Select(s => ToDto(s))
+                .ToListAsync();
+
+            return Results.Ok(shipments);
+        });
+
+        // GET shipment by tracking number (any authenticated user)
+        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
+        {
+            var shipment = await db.Shipments
+                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
+
+            return shipment is null
+                ? Results.NotFound(new { Message = "Shipment not found" })
+                : Results.Ok(ToDto(shipment));
+        });
+
+        // PUT update shipment status (dispatchers only)
+        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async (
+            int id, UpdateStatusRequest request, ApplicationDbContext db) =>
+        {
+            var shipment = await db.Shipments.FindAsync(id);
+            if (shipment is null)
+                return Results.NotFound();
+
+            shipment.Status = request.NewStatus;
+            if (request.NewStatus == ShipmentStatus.Delivered)
+                shipment.ActualDelivery = DateTime.UtcNow;
+
+            await db.SaveChangesAsync();
+            return Results.Ok(ToDto(shipment));
+        });
+
+        // POST create shipment (dispatchers only)
+        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (
+            ShipmentDto dto, ApplicationDbContext db) =>
+        {
+            var shipment = new Shipment
+            {
+                TrackingNumber = dto.TrackingNumber,
+                Origin = dto.Origin,
+                Destination = dto.Destination,
+                Status = dto.Status,
+                ShippedDate = dto.ShippedDate,
+                EstimatedDelivery = dto.EstimatedDelivery,
+                RecipientName = dto.RecipientName,
+                CustomerEmail = dto.CustomerEmail
+            };
+
+            db.Shipments.Add(shipment);
+            await db.SaveChangesAsync();
+            return Results.Created($"/api/shipments/track/{shipment.TrackingNumber}", ToDto(shipment));
+        });
+    }
+
+    private static ShipmentDto ToDto(Shipment s) => new()
+    {
+        Id = s.Id,
+        TrackingNumber = s.TrackingNumber,
+        Origin = s.Origin,
+        Destination = s.Destination,
+        Status = s.Status,
+        ShippedDate = s.ShippedDate,
+        EstimatedDelivery = s.EstimatedDelivery,
+        ActualDelivery = s.ActualDelivery,
+        RecipientName = s.RecipientName,
+        CustomerEmail = s.CustomerEmail
+    };
+}
