@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container-fluid mt-3">
    <h2>🚚 Dispatcher Dashboard</h2>

    <div class="row mb-3 g-2">
        <div class="col-md-4">
            <input class="form-control" placeholder="Search tracking #, destination, recipient…"
                   @bind="searchText" @bind:event="oninput" @onkeyup="HandleSearch" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="statusFilter" @bind:after="LoadShipments">
                <option value="">All Statuses</option>
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
        <div class="col-md-3">
            <button class="btn btn-success" @onclick="() => showCreateForm = !showCreateForm">
                @(showCreateForm ? "Cancel" : "+ New Shipment")
            </button>
        </div>
    </div>

    @if (showCreateForm)
    {
        <div class="card mb-3">
            <div class="card-body">
                <h5>Create New Shipment</h5>
                <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="createShipment">
                    <DataAnnotationsValidator />
                    <div class="row g-2">
                        <div class="col-md-3">
                            <label class="form-label">Tracking #</label>
                            <InputText class="form-control" @bind-Value="newShipment.TrackingNumber" />
                        </div>
                        <div class="col-md-3">
                            <label class="form-label">Origin</label>
                            <InputText class="form-control" @bind-Value="newShipment.Origin" />
                        </div>
                        <div class="col-md-3">
                            <label class="form-label">Destination</label>
                            <InputText class="form-control" @bind-Value="newShipment.Destination" />
                        </div>
                        <div class="col-md-3">
                            <label class="form-label">Recipient</label>
                            <InputText class="form-control" @bind-Value="newShipment.RecipientName" />
                        </div>
                        <div class="col-md-3">
                            <label class="form-label">Customer Email</label>
                            <InputText class="form-control" @bind-Value="newShipment.CustomerEmail" />
                        </div>
                        <div class="col-md-3">
                            <label class="form-label">Shipped Date</label>
                            <InputDate class="form-control" @bind-Value="newShipmentDate" />
                        </div>
                        <div class="col-md-3">
                            <label class="form-label">Est. Delivery</label>
                            <InputDate class="form-control" @bind-Value="newEstDelivery" />
                        </div>
                        <div class="col-md-3 d-flex align-items-end">
                            <button type="submit" class="btn btn-primary">Create</button>
                        </div>
                    </div>
                </EditForm>
            </div>
        </div>
    }

    @if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    @if (shipments is null)
    {
        <p><em>Loading shipments…</em></p>
    }
    else if (shipments.Count == 0)
    {
        <div class="alert alert-info">No shipments found.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Recipient</th>
                        <th>Status</th>
                        <th>Shipped</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var shipment in shipments)
                    {
                        <tr>
                            <td><strong>@shipment.TrackingNumber</strong></td>
                            <td>@shipment.Origin</td>
                            <td>@shipment.Destination</td>
                            <td>@shipment.RecipientName</td>
                            <td>
                                <span class="badge @GetStatusBadgeClass(shipment.Status)">
                                    @shipment.Status
                                </span>
                            </td>
                            <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                            <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                            <td>
                                <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                        value="@shipment.Status"
                                        @onchange="(e) => UpdateStatus(shipment, e)">
                                    @foreach (var s in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@s" selected="@(shipment.Status == s)">@s</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<ShipmentDto>? shipments;
    private string searchText = "";
    private string statusFilter = "";
    private string? errorMessage;
    private bool showCreateForm;

    private ShipmentDto newShipment = new();
    private DateTime newShipmentDate = DateTime.UtcNow;
    private DateTime newEstDelivery = DateTime.UtcNow.AddDays(5);

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            errorMessage = null;
            var url = "/api/shipments?";
            if (!string.IsNullOrEmpty(statusFilter))
                url += $"status={statusFilter}&";
            if (!string.IsNullOrEmpty(searchText))
                url += $"search={Uri.EscapeDataString(searchText)}";

            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>(url);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task HandleSearch()
    {
        await LoadShipments();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            try
            {
                var response = await Http.PutAsJsonAsync(
                    $"/api/shipments/{shipment.Id}/status",
                    new UpdateStatusRequest { NewStatus = newStatus });

                if (response.IsSuccessStatusCode)
                {
                    var updated = await response.Content.ReadFromJsonAsync<ShipmentDto>();
                    if (updated is not null)
                    {
                        var idx = shipments!.FindIndex(s => s.Id == shipment.Id);
                        if (idx >= 0) shipments[idx] = updated;
                    }
                }
            }
            catch (Exception ex)
            {
                errorMessage = $"Failed to update status: {ex.Message}";
            }
        }
    }

    private async Task CreateShipment()
    {
        try
        {
            newShipment.ShippedDate = DateTime.SpecifyKind(newShipmentDate, DateTimeKind.Utc);
            newShipment.EstimatedDelivery = DateTime.SpecifyKind(newEstDelivery, DateTimeKind.Utc);
            newShipment.Status = ShipmentStatus.Pending;

            var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
            if (response.IsSuccessStatusCode)
            {
                newShipment = new();
                newShipmentDate = DateTime.UtcNow;
                newEstDelivery = DateTime.UtcNow.AddDays(5);
                showCreateForm = false;
                await LoadShipments();
            }
            else
            {
                errorMessage = "Failed to create shipment.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error creating shipment: {ex.Message}";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-light text-dark"
    };
}

@page "/track"
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2>📋 Track Your Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input class="form-control" placeholder="Enter tracking number (e.g. TRK-20260501-001)"
                       @bind="inputTracking" @onkeyup="HandleKeyUp" />
                <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm" role="status"></span>
                    }
                    else
                    {
                        <span>Track</span>
                    }
                </button>
            </div>
        </div>
    </div>

    @if (errorMessage is not null)
    {
        <div class="alert alert-warning">@errorMessage</div>
    }

    @if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header bg-dark text-white">
                <h4 class="mb-0">Shipment: @shipment.TrackingNumber</h4>
            </div>
            <div class="card-body">
                <div class="row g-3">
                    <div class="col-md-6">
                        <h6 class="text-muted">Route</h6>
                        <p class="fs-5">@shipment.Origin → @shipment.Destination</p>
                    </div>
                    <div class="col-md-6">
                        <h6 class="text-muted">Recipient</h6>
                        <p class="fs-5">@shipment.RecipientName</p>
                    </div>
                    <div class="col-md-4">
                        <h6 class="text-muted">Status</h6>
                        <span class="badge fs-6 @GetStatusBadgeClass(shipment.Status)">
                            @shipment.Status
                        </span>
                    </div>
                    <div class="col-md-4">
                        <h6 class="text-muted">Shipped Date</h6>
                        <p>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                    </div>
                    <div class="col-md-4">
                        <h6 class="text-muted">Estimated Delivery</h6>
                        <p class="fw-bold">@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                    </div>

                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <div class="col-12">
                            <div class="alert alert-success">
                                ✅ Delivered on @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")
                            </div>
                        </div>
                    }
                    else if (shipment.Status == ShipmentStatus.Delayed)
                    {
                        <div class="col-12">
                            <div class="alert alert-warning">
                                ⚠️ This shipment is currently delayed. The estimated delivery date may change.
                            </div>
                        </div>
                    }
                </div>

                <!-- Progress visualization -->
                <hr />
                <h6 class="text-muted mb-3">Shipment Progress</h6>
                <div class="d-flex justify-content-between position-relative mb-3">
                    @{
                        var steps = new[] {
                            (ShipmentStatus.Pending, "Pending"),
                            (ShipmentStatus.PickedUp, "Picked Up"),
                            (ShipmentStatus.InTransit, "In Transit"),
                            (ShipmentStatus.OutForDelivery, "Out for Delivery"),
                            (ShipmentStatus.Delivered, "Delivered")
                        };
                        var currentStep = GetStepIndex(shipment.Status);
                    }
                    @for (int i = 0; i < steps.Length; i++)
                    {
                        var isActive = i <= currentStep;
                        <div class="text-center flex-fill">
                            <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-primary text-white" : "bg-light text-muted border")"
                                 style="width: 36px; height: 36px;">
                                @(i + 1)
                            </div>
                            <div class="small mt-1 @(isActive ? "fw-bold" : "text-muted")">@steps[i].Item2</div>
                        </div>
                    }
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string inputTracking = "";
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isLoading;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrEmpty(TrackingNumber))
        {
            inputTracking = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task HandleKeyUp(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(inputTracking)) return;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(inputTracking.Trim())}");
            if (response.IsSuccessStatusCode)
            {
                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            }
            else
            {
                errorMessage = "No shipment found with that tracking number. Please check and try again.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error looking up shipment: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private static int GetStepIndex(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 0,
        ShipmentStatus.PickedUp => 1,
        ShipmentStatus.InTransit => 2,
        ShipmentStatus.OutForDelivery => 3,
        ShipmentStatus.Delivered => 4,
        ShipmentStatus.Delayed => 2,
        ShipmentStatus.Returned => 0,
        _ => 0
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-light text-dark"
    };
}

